// Post-process: fix any \\uXXXX that leaked through
let written = fs.readFileSync(outPath, 'utf8');
const escapeCount = (written.match(/\\u[0-9a-fA-F]{4}/g) || []).length;
console.log('Unicode escape sequences found:', escapeCount);
if (escapeCount > 0) {
  written = written.replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)));
  fs.writeFileSync(outPath, written, 'utf8');
  console.log('Fixed unicode escapes');
}

